package studio.dabble.protomorphic

import com.squareup.wire.AnyMessage
import com.squareup.wire.ProtoAdapter

/**
 * Packs [value] into a `google.protobuf.Any`. Wire's `AnyMessage.pack` only accepts Wire's own
 * `Message` subclasses; messages generated by protomorphic carry their type URL on their adapter instead.
 * Unpack with `AnyMessage.unpack(T.ADAPTER)`.
 */
public fun <T : Any> ProtoAdapter<T>.packAny(value: T): AnyMessage =
    AnyMessage(
        typeUrl = typeUrl ?: error("$this has no type URL, so it cannot be packed into an Any"),
        value = encodeByteString(value),
    )
